#!/usr/bin/env bash
# Cloud-side coding agent runner (generated by pi-cnb-cloud).
#
# Contract with the pipeline:
#   in  AGENT_TASK            the natural-language task (required)
#       AGENT_TITLE           build / PR title (optional)
#       AGENT_RUN_ID          correlation id (optional)
#       AGENT_TEST_CMD        test command; falls back to .pi/cnb-cloud.json
#       AGENT_MAX_ITERATIONS  agent passes; default 2
#       AGENT_MODEL / AGENT_PROVIDER / AGENT_BASE_URL / AGENT_API_KEY
#   out ===PI-CNB-RESULT=== followed by one JSON line, plus a pushed branch/PR.
#
# Deliberately avoids `set -e`: a failed agent must still push and print a
# result marker so the local side stays truthful.

set -uo pipefail

MARKER="===PI-CNB-RESULT==="
WORKSPACE="${CNB_BUILD_WORKSPACE:-/workspace}"
ART="/tmp/pi-cnb-agent"
mkdir -p "$ART"

log() { printf '%s\n' "$*"; }
die() { log "✗ $*"; finish "error" "$*"; exit 1; }

cd "$WORKSPACE" 2>/dev/null || { log "✗ workspace not found: $WORKSPACE"; exit 1; }

if [ -z "${AGENT_TASK:-}" ]; then
  log "✗ AGENT_TASK 为空：请通过触发参数 env.AGENT_TASK 传入任务描述。"
  exit 2
fi

BASE_BRANCH="${CNB_BRANCH:-main}"
RUN_ID="${AGENT_RUN_ID:-$(date +%Y%m%d-%H%M%S)}"
SAFE_ID="$(printf '%s' "$RUN_ID" | tr -c 'A-Za-z0-9._-' '-' | cut -c1-48)"
WORK_BRANCH="agent/${SAFE_ID}"
TITLE="${AGENT_TITLE:-agent: $(printf '%s' "$AGENT_TASK" | head -n1 | cut -c1-60)}"

# ---------------------------------------------------------------- config -----
CONFIG_FILE=".pi/cnb-cloud.json"

json_get() { # json_get <file> <dot.path>
  node -e '
    const fs = require("fs");
    const file = process.argv[1], path = process.argv[2];
    try {
      const value = path.split(".").reduce((o, k) => (o == null ? o : o[k]), JSON.parse(fs.readFileSync(file, "utf8")));
      if (value !== undefined && value !== null && typeof value !== "object") process.stdout.write(String(value));
    } catch {}
  ' "$1" "$2" 2>/dev/null
}

cfg() { json_get "$CONFIG_FILE" "$1"; }

TEST_CMD="${AGENT_TEST_CMD:-$(cfg testCommand)}"
MAX_ITERS="${AGENT_MAX_ITERATIONS:-$(cfg maxIterations)}"
MAX_ITERS="${MAX_ITERS:-2}"
MODEL="${AGENT_MODEL:-$(cfg model)}"
PROVIDER="${AGENT_PROVIDER:-$(cfg provider)}"
BASE_URL="${AGENT_BASE_URL:-$(cfg baseUrl)}"
API_KIND="${AGENT_API:-$(cfg api)}"

# ------------------------------------------------------------- lifecycle -----
COMMIT_SHA=""
PR_URL=""
PUSHED=0
SUMMARY=""
TEST_STATUS="skipped"
FINAL_STATUS="error"
FINAL_MESSAGE=""

finish() { # finish <status> <message>
  FINAL_STATUS="$1"
  FINAL_MESSAGE="$2"

  local web="${CNB_WEB_PROTOCOL:-https}://${CNB_WEB_HOST:-cnb.cool}/${CNB_REPO_SLUG:-}"
  # Machine-readable result the local extension can recover from the build log.
  MARKER="$MARKER" FINAL_STATUS="$FINAL_STATUS" FINAL_MESSAGE="$FINAL_MESSAGE" \
  WORK_BRANCH="$WORK_BRANCH" BASE_BRANCH="$BASE_BRANCH" PR_URL="$PR_URL" \
  PUSHED="$PUSHED" TEST_STATUS="$TEST_STATUS" SUMMARY="$SUMMARY" \
  CNB_BUILD_ID="${CNB_BUILD_ID:-}" CNB_BUILD_WEB_URL="${CNB_BUILD_WEB_URL:-}" \
  CNB_REPO_SLUG="${CNB_REPO_SLUG:-}" node -e '
    process.stdout.write(process.env.MARKER + "\n" + JSON.stringify({
      status: process.env.FINAL_STATUS,
      message: process.env.FINAL_MESSAGE,
      branch: process.env.WORK_BRANCH,
      base: process.env.BASE_BRANCH,
      pr: process.env.PR_URL || "",
      changed: process.env.PUSHED === "1",
      tests: process.env.TEST_STATUS,
      summary: process.env.SUMMARY || "",
      sn: process.env.CNB_BUILD_ID || "",
      buildUrl: process.env.CNB_BUILD_WEB_URL || "",
      repo: process.env.CNB_REPO_SLUG || "",
    }) + "\n");
  '
}

trap 'finish "error" "流水线被中断"' INT TERM

# --------------------------------------------------------------- git prep -----
git config user.name "${GIT_AUTHOR_NAME:-pi-cloud-agent}"
git config user.email "${GIT_AUTHOR_EMAIL:-pi-cloud-agent@cnb.cool}"
git config --global --add safe.directory "$WORKSPACE" 2>/dev/null || true

log "→ 任务: $AGENT_TASK"
log "→ 仓库: ${CNB_REPO_SLUG:-?}  基分支: $BASE_BRANCH  工作分支: $WORK_BRANCH"
log "→ 模型: ${MODEL:-<pi default>}  测试: ${TEST_CMD:-<none>}  轮次: $MAX_ITERS"

if ! git checkout -B "$WORK_BRANCH" >/dev/null 2>&1; then
  die "无法创建分支 $WORK_BRANCH"
fi

# --------------------------------------------------------------- model ------
if [ -n "$BASE_URL" ] && [ -n "$MODEL" ]; then
  mkdir -p "$HOME/.pi/agent"
  AGENT_MODEL_ID="$MODEL" AGENT_BASE_URL_VALUE="$BASE_URL" AGENT_API_KIND="${API_KIND:-openai-completions}" \
  node -e '
    const fs = require("fs"), path = process.env.HOME + "/.pi/agent/models.json";
    const provider = {
      baseUrl: process.env.AGENT_BASE_URL_VALUE,
      api: process.env.AGENT_API_KIND,
      apiKey: "$AGENT_API_KEY",
      models: [{ id: process.env.AGENT_MODEL_ID, name: process.env.AGENT_MODEL_ID }],
    };
    fs.writeFileSync(path, JSON.stringify({ providers: { cloud: provider } }, null, 2));
    process.stdout.write("→ 已写入 " + path + "\n");
  '
  PROVIDER="${PROVIDER:-cloud}"
fi

if ! command -v pi >/dev/null 2>&1 || ! pi --version >/dev/null 2>&1; then
  log "→ 镜像内没有可用的 pi，安装/修复 @earendil-works/pi-coding-agent"
  npm install -g @earendil-works/pi-coding-agent --no-fund --no-audit >"$ART/npm.log" 2>&1 \
    || die "pi 安装失败，见 $ART/npm.log"
fi

if [ -z "$MODEL" ] && [ ! -f "$HOME/.pi/agent/auth.json" ] && [ ! -f "$HOME/.pi/agent/models.json" ]; then
  die "未配置模型：请设置 AGENT_BASE_URL + AGENT_MODEL + AGENT_API_KEY（通过 CNB 密钥仓库 imports），或在 .pi/cnb-cloud.json 配置 model/baseUrl/api。"
fi

PROVIDER_ARGS=()
[ -n "$PROVIDER" ] && PROVIDER_ARGS+=(--provider "$PROVIDER")
[ -n "$MODEL" ] && PROVIDER_ARGS+=(--model "$MODEL")

# -------------------------------------------------------------- prompt ------
build_prompt() { # build_prompt <iteration> <previous-failure-log>
  local iteration="$1" prev="$2"
  cat <<EOF
你是一个在 CNB（腾讯云原生构建）容器中无人值守运行的编码 agent。

任务：
$AGENT_TASK

环境事实：
- 仓库已 checkout 到 /workspace，当前基分支为 $BASE_BRANCH，你在临时分支 $WORK_BRANCH 上工作。
- 你拥有 read / bash / edit / write 工具，可以自由运行编译、测试和静态检查。
- 没有任何人类在线，你必须自己做决定，禁止提出需要确认的问题。

必须遵守：
1. 只做任务要求的最小改动，保持现有代码风格；不要重构无关代码，不要改 CI 配置。
2. 修改后运行测试（优先 \`$TEST_CMD\`）；测试失败就继续修，直到通过或确认无法在本次修复。
3. 不要执行 git commit / git push / git checkout -b，提交和推送由外层脚本负责。
4. 不要打印或写入任何密钥；不要联网下载与任务无关的东西。
5. 完成后用简洁的 Markdown 输出最终报告，必须包含：做了什么、改了哪些文件、测试结果（命令 + 通过/失败）、以及任何遗留风险。
EOF

  if [ -n "$prev" ] && [ -s "$prev" ]; then
    cat <<'EOF'

上一轮修改后测试失败，以下是失败输出（已截断）。请定位根因并修复，不要只是改测试让它通过：
```
EOF
    tail -c 4000 "$prev"
    printf '\n```\n'
  fi
}

extract_summary() { # extract_summary <jsonl>
  node -e '
    const fs = require("fs");
    let last = "";
    for (const line of fs.readFileSync(process.argv[1], "utf8").split("\n")) {
      if (!line.trim()) continue;
      let event;
      try { event = JSON.parse(line); } catch { continue; }
      if (event.type !== "message_end") continue;
      const message = event.message;
      if (!message || message.role !== "assistant" || !Array.isArray(message.content)) continue;
      const text = message.content.filter((b) => b.type === "text").map((b) => b.text).join("\n").trim();
      if (text) last = text;
    }
    process.stdout.write(last);
  ' "$1" 2>/dev/null
}

# CNB kills a stage that prints nothing for 10 minutes; long agent runs need a pulse.
heartbeat() { # heartbeat <out-file> <start-epoch> <pi-pid>
  local out="$1" start="$2" pid="$3" bytes tools last now
  while kill -0 "$pid" 2>/dev/null; do
    sleep 30
    kill -0 "$pid" 2>/dev/null || break
    now=$(date +%s)
    bytes=$(wc -c <"$out" 2>/dev/null || echo 0)
    tools=$(grep -c '"type":"tool_execution_start"' "$out" 2>/dev/null || true)
    last=$(grep -o '"toolName":"[^"]*"' "$out" 2>/dev/null | tail -n1 | cut -d'"' -f4)
    log "… pi 运行 $(( now - start ))s，事件流 ${bytes// /}B，工具 ${tools:-0} 次${last:+，最近: $last}"
  done
}

# ---------------------------------------------------------------- agent -----
PREV_FAILURE=""
for i in $(seq 1 "$MAX_ITERS"); do
  PROMPT_FILE="$ART/prompt-$i.md"
  OUT="$ART/agent-$i.jsonl"
  ERR="$ART/agent-$i.err"

  build_prompt "$i" "$PREV_FAILURE" >"$PROMPT_FILE"

  log "→ 第 $i/$MAX_ITERS 轮：pi 开始执行（$(pi --version 2>&1 | head -n1)）"
  START_TS=$(date +%s)
  pi --mode json --no-session "${PROVIDER_ARGS[@]}" "$(cat "$PROMPT_FILE")" \
    >"$OUT" 2>"$ERR" &
  PI_PID=$!
  heartbeat "$OUT" "$START_TS" "$PI_PID" &
  HB_PID=$!
  wait "$PI_PID"
  PI_CODE=$?
  kill "$HB_PID" 2>/dev/null
  wait "$HB_PID" 2>/dev/null

  TOOLS=$(grep -c '"type":"tool_execution_start"' "$OUT" 2>/dev/null || true)
  LAST_TOOL=$(grep -o '"toolName":"[^"]*"' "$OUT" 2>/dev/null | tail -n1 | cut -d'"' -f4)
  log "→ 工具调用 ${TOOLS:-0} 次${LAST_TOOL:+，最近 $LAST_TOOL}"

  SUMMARY="$(extract_summary "$OUT")"
  [ -z "$SUMMARY" ] && SUMMARY="$(tail -c 1500 "$ERR")"
  if [ "${TOOLS:-0}" = "0" ] && [ -s "$OUT" ]; then
    log "⚠ 本轮 0 次工具调用，最后一条 assistant 文本（截断）："
    printf '%s\n' "$SUMMARY" | head -c 900
    log ""
  fi

  log "→ pi 退出码 $PI_CODE，事件流 $(wc -c <"$OUT") 字节，stderr $(wc -c <"$ERR") 字节"
  if [ ! -s "$OUT" ]; then
    log "⚠ 本轮没有产生事件流；stderr 前 25 行："
    head -n 25 "$ERR" 2>/dev/null || true
    log "⚠ stdout 前 25 行："
    head -n 25 "$OUT" 2>/dev/null || true
  elif [ "$PI_CODE" -ne 0 ]; then
    log "⚠ pi 非零退出；stderr 前 25 行："
    head -n 25 "$ERR" 2>/dev/null || true
  fi

  if [ -z "$TEST_CMD" ]; then
    TEST_STATUS="skipped"
    break
  fi

  log "→ 运行测试：$TEST_CMD"
  if bash -lc "$TEST_CMD" >"$ART/test-$i.log" 2>&1; then
    TEST_STATUS="passed"
    log "✓ 测试通过"
    break
  fi

  TEST_STATUS="failed"
  PREV_FAILURE="$ART/test-$i.log"
  log "✗ 测试未通过（第 $i 轮）"
  tail -n 20 "$PREV_FAILURE" || true

  if [ "$i" = "$MAX_ITERS" ]; then
    log "→ 已达到最大轮次，保留当前改动并上报失败测试"
  fi
done

# ---------------------------------------------------------- commit / push ----
git add -A
if git diff --cached --quiet; then
  log "→ 没有代码变更"
  FINAL_STATUS="$([ "$TEST_STATUS" = "failed" ] && echo error || echo success)"
  finish "$FINAL_STATUS" "agent 未产生代码变更"
  exit "$([ "$FINAL_STATUS" = "error" ] && echo 1 || echo 0)"
fi

git commit -q -m "chore(agent): $TITLE" -m "${SUMMARY:0:3000}" || die "git commit 失败"

if [ -z "${CNB_TOKEN:-}" ]; then
  die "缺少 CNB_TOKEN，无法推送分支"
fi

PUSH_URL="${CNB_WEB_PROTOCOL:-https}://cnb:${CNB_TOKEN}@${CNB_WEB_HOST:-cnb.cool}/${CNB_REPO_SLUG}.git"
if git push -q "$PUSH_URL" "HEAD:refs/heads/$WORK_BRANCH" 2>"$ART/push.log"; then
  PUSHED=1
  log "✓ 已推送分支 $WORK_BRANCH"
  COMMIT_SHA="$(git rev-parse --short HEAD)"
else
  log "✗ 推送失败："
  tail -n 30 "$ART/push.log" || true
  SUMMARY="$SUMMARY"$'\n\n> ⚠ 分支推送失败，代码仅存在于本次构建容器中。'
fi

# ------------------------------------------------------------------- PR ------
if [ "$PUSHED" = "1" ] && [ -n "${CNB_API_ENDPOINT:-}" ]; then
  BODY_FILE="$ART/pr-body.md"
  printf '## %s\n\n%s\n\n---\n- 基分支: `%s`\n- 工作分支: `%s`\n- 测试: %s\n- 构建: %s\n- 由 [pi-cnb-cloud](https://pi.dev) 自动生成\n' \
    "$TITLE" "$SUMMARY" "$BASE_BRANCH" "$WORK_BRANCH" "$TEST_STATUS" "${CNB_BUILD_WEB_URL:-}" >"$BODY_FILE"

  PR_URL="$(node --input-type=module - "$CNB_API_ENDPOINT" "$CNB_REPO_SLUG" "$CNB_TOKEN" "$WORK_BRANCH" "$BASE_BRANCH" "$TITLE" "$BODY_FILE" <<'NODE'
import fs from "node:fs";
const [endpoint, repo, token, head, base, title, bodyFile] = process.argv.slice(2);
const url = `${endpoint.replace(/\/+$/, "")}/${repo.split("/").map(encodeURIComponent).join("/")}/-/pulls`;
const body = fs.readFileSync(bodyFile, "utf8");

const res = await fetch(url, {
  method: "POST",
  headers: {
    Accept: "application/vnd.cnb.api+json",
    Authorization: `Bearer ${token}`,
    "Content-Type": "application/json",
  },
  body: JSON.stringify({ title, body, head, base }),
});

const text = await res.text();
if (!res.ok) {
  process.stderr.write(`PR 创建失败 ${res.status}: ${text.slice(0, 300)}\n`);
  process.exit(1);
}
let data = {};
try { data = JSON.parse(text); } catch {}
const fallback = `${process.env.CNB_WEB_PROTOCOL || "https"}://${process.env.CNB_WEB_HOST || "cnb.cool"}/${repo}/-/pulls/${data.number ?? ""}`;
process.stdout.write(data.web_url || data.url || data.html_url || data.link || (data.number ? fallback : ""));
NODE
)" || PR_URL=""

  if [ -n "$PR_URL" ]; then
    log "✓ 已创建 PR: $PR_URL"
  else
    log "⚠ PR 未创建（可能缺少 repo-pr:rw 权限或仓库关闭了 PR），分支已推送"
  fi
fi

# --------------------------------------------------------------- result ------
if [ "$TEST_STATUS" = "failed" ]; then
  FINAL_STATUS="error"
  FINAL_MESSAGE="测试未通过（已推送分支供审查）"
elif [ "$PUSHED" = "1" ]; then
  FINAL_STATUS="success"
  FINAL_MESSAGE="已完成并推送分支"
else
  FINAL_STATUS="error"
  FINAL_MESSAGE="代码改动未能推送"
fi

finish "$FINAL_STATUS" "$FINAL_MESSAGE"
trap - INT TERM
[ "$FINAL_STATUS" = "success" ] && exit 0 || exit 1